<?php require 'config.php'; require 'core/Database.php'; $db = Database::getInstance()->getConnection(); try { $db->exec("ALTER TABLE rent_profiles ADD COLUMN default_payment_method ENUM('Cash', 'Bank Transfer', 'Mobile Money', 'Cheque', 'Other') DEFAULT 'Cash'"); echo 'rent_profiles altered\n'; } catch(Exception $e) { echo $e->getMessage() . '\n'; } try { $db->exec("ALTER TABLE contracts ADD COLUMN payment_method_rule ENUM('Any Method', 'Bank Transfer Only', 'Cash Only', 'Mobile Money Only') DEFAULT 'Any Method'"); echo 'contracts altered\n'; } catch(Exception $e) { echo $e->getMessage() . '\n'; } try { $db->exec("ALTER TABLE rent_invoices ADD COLUMN payment_method ENUM('Cash', 'Bank Transfer', 'Mobile Money', 'Cheque', 'Other') NULL, ADD COLUMN payment_date DATE NULL, ADD COLUMN reference_number VARCHAR(100) NULL, ADD COLUMN bank_name VARCHAR(100) NULL, ADD COLUMN account_number VARCHAR(100) NULL, ADD COLUMN proof_of_payment VARCHAR(255) NULL"); echo 'rent_invoices altered\n'; } catch(Exception $e) { echo $e->getMessage() . '\n'; }
